{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Push for a higher general cap, such as 30-50% of price, depending on negotiation."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Push for: related claims aggregated for de minimis purposes, a lower basket, and a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Push for at least 24-36 months for general warranties, with longer periods for fundamental and tax matters."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Make title, capacity and authority fundamental (full price cap, six-year period)."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Carve out fraud from every limitation and non-reliance clause."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete the general data-room disclosure. Require specific disclosure against specific warranties, with fair disclosure of reasonable detail."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the buyer-knowledge bar and replace it with an express pro-sandbagging clause, so that our knowledge does not prevent a claim."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Make written Bluefen consent, in a form acceptable to us and without adverse conditions, a condition precedent that only we can waive."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "The debt should be paid out of the Seller's proceeds at Completion against a payoff letter and a PPSR discharge."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Those costs should be quantified and the full amount treated as a Seller cost, deducted from price or paid by the Seller before Completion."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Add an IP title warranty and a specific indemnity covering all third-party and ownership claims arising from the Ironquay work, outside the general cap."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require an immediate forensic and privacy-law assessment, paid for by the Seller, with access to the results."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PUSHBACK",
      "evidence": "Treat any accrued or non-ordinary-course amounts as debt-like."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Known issues should be dealt with by specific indemnities and price adjustments, not by consuming the cap."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Require searches (ASIC extract, PPSR, certified share register, share transfer and any share security), and confirm stamp duty."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Require tax warranties and a pre-Completion tax indemnity with a longer period, aligned with the tax amendment period."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

